'use strict';
const FashionUI=(()=>{
  const cart=new Set();let tab='전체',notice='마음에 드는 의상을 장바구니에 담아 보세요.';
  const item=id=>FashionCatalog.find(i=>i.id===id);
  const image=i=>Wardrobe.items.find(w=>w.id===i.id)?.iconImg||i.iconImg||'';
  function connectProductImages(){document.querySelectorAll('.product-image img').forEach(img=>{img.onerror=()=>{const note=document.createElement('small');note.textContent='이미지 준비 중';img.replaceWith(note)};if(img.complete&&!img.naturalWidth)img.onerror()})}
  function shop(category='전체'){tab=category;modal('햇살 부티크','<div id="boutique"></div>');$('#modal').classList.add('wardrobe-modal');renderShop()}
  function renderShop(){const d=economy.data;for(const id of cart)if(d.owned.includes(id))cart.delete(id);
    $('#boutique').innerHTML=`<div class="boutique-heading"><p>일상에 살짝 더하는 사랑스러움</p><b>◒ ${d.shells.toLocaleString()} 조개</b></div><div class="wardrobe-tabs">${['전체','상의','하의','아우터','모자','소품'].map(t=>`<button data-style="${t}" aria-pressed="${tab===t}">${t}</button>`).join('')}</div><div class="shop-layout"><section class="shop-grid">${FashionCatalog.filter(i=>i.price&&(tab==='전체'||(i.category||Wardrobe.items.find(w=>w.id===i.id)?.category)===tab)).map(i=>`<article class="product"><div class="product-image"><img src="${image(i)}" alt="${i.name} 의상 이미지"></div><small>${i.category||i.tag}</small><h3>${i.name}</h3><b>◒ ${i.price}</b><button data-add="${i.id}" ${d.owned.includes(i.id)||cart.has(i.id)?'disabled':''}>${d.owned.includes(i.id)?'보유 중':cart.has(i.id)?'담았어요':'장바구니 담기'}</button>${d.owned.includes(i.id)?`<button class="try-owned" data-wear-owned="${i.id}">지금 입어 보기</button>`:''}</article>`).join('')}</section><aside class="cart"><h3>나의 장바구니 <span>${cart.size}</span></h3>${[...cart].map(id=>`<div class="cart-row"><span>${item(id).name}<small>${item(id).price} 조개</small></span><button data-remove-cart="${id}" aria-label="${item(id).name} 장바구니에서 빼기">×</button></div>`).join('')||'<p>아직 담긴 옷이 없어요.</p>'}<div class="cart-total">합계 <b>${[...cart].reduce((n,id)=>n+item(id).price,0)} 조개</b></div><button class="primary" id="checkout" ${cart.size?'':'disabled'}>함께 구매하기</button><p>구매한 의상은 옷장에 보관돼요.</p><p>구매 후 옷장에서 입어 보세요. 섬 위 캐릭터에도 바로 반영돼요.</p></aside></div><p class="fashion-status" role="status">${notice}</p><button class="item" id="shopWardrobe">내 옷장 열기 →</button>`;
    connectProductImages();
    document.querySelectorAll('[data-wear-owned]').forEach(b=>b.onclick=()=>{Wardrobe.equip(b.dataset.wearOwned);Wardrobe.open(modal)});
    document.querySelectorAll('[data-style]').forEach(b=>b.onclick=()=>{tab=b.dataset.style;renderShop()});document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{cart.add(b.dataset.add);notice='장바구니에 담았어요. 구매 전까지 조개는 사용하지 않아요.';renderShop()});document.querySelectorAll('[data-remove-cart]').forEach(b=>b.onclick=()=>{cart.delete(b.dataset.removeCart);renderShop()});$('#checkout').onclick=()=>{const result=economy.purchase([...cart]);notice=result.message+(economy.storageOK?'':' · 브라우저 저장 불가: 이번 방문에만 유지');if(result.ok)cart.clear();renderShop()};$('#shopWardrobe').onclick=()=>Wardrobe.open(modal);
  }
  function workshop(){modal('포근 의상 공방','<div id="workshop"></div>');$('#modal').classList.add('wardrobe-modal');renderCraft('목화 한 줌으로 나만의 옷을 만들어 보세요.')}
  function renderCraft(message){const d=economy.data;$('#workshop').innerHTML=`<div class="material-strip"><span>◒ 조개 <b>${d.shells.toLocaleString()}</b></span><span>☁ 폭신목화 <b>${d.inventory.cotton}</b></span><span>✧ 달빛 마법 가루 <b>${d.inventory.moonDust}</b></span></div><p>기본 제작 또는 달빛 재료를 넣는 유니크 합성을 선택하세요.</p><div class="recipe-grid">${FashionCatalog.filter(i=>i.recipe).map(i=>{const r=i.recipe,owned=d.owned.includes(i.id),enough=d.shells>=r.shells&&d.inventory.cotton>=r.cotton&&d.inventory.moonDust>=(r.moonDust||0);return `<article class="product recipe ${i.unique?'unique':''}"><div class="product-image"><img src="${image(i)}" alt="${i.name} 의상 이미지">${i.unique?'<span class="unique-sparkles" aria-hidden="true">✧ · ✦ · ✧</span>':''}</div><small>${i.unique?'UNIQUE · 달빛 합성':'BASIC · 기본 제작'}</small><h3>${i.name}</h3><p>폭신목화 ${r.cotton}개 + 조개 ${r.shells}${r.moonDust?`<br>+ 달빛 마법 가루 ${r.moonDust}개`:''}</p><button data-craft="${i.id}" ${owned||!enough?'disabled':''}>${owned?'제작 완료':!enough?'재료 부족':i.unique?'유니크 합성하기':'의상 만들기'}</button>${i.unique?'<p>착용하면 반짝이는 파티클이 맴돌아요.</p>':''}</article>`}).join('')}</div><p class="fashion-status" role="status">${message}</p><section class="craft-quest"><h3>달빛 가루를 찾는 작은 부탁</h3><p>몽글당근 3개 수확 · ${Math.min(3,d.carrotsHarvested)} / 3<br>보상: 달빛 마법 가루 1개 · 한 번만 받을 수 있어요.</p><button class="primary" id="claimDust" ${d.claimed.includes('first-harvest')||d.carrotsHarvested<3?'disabled':''}>${d.claimed.includes('first-harvest')?'보상 수령 완료':'퀘스트 보상 받기'}</button></section><button class="item" id="craftWardrobe">완성한 옷 입으러 가기 →</button>`;
    connectProductImages();
    document.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>{const result=economy.craft(b.dataset.craft);renderCraft(result.message+(economy.storageOK?'':' · 저장 불가: 이번 방문에만 유지'));if(result.ok&&item(b.dataset.craft).unique){$('#workshop').classList.remove('synthesis-success');void $('#workshop').offsetWidth;$('#workshop').classList.add('synthesis-success')}});$('#claimDust').onclick=()=>{const result=economy.claimQuest();renderCraft(result.message)};$('#craftWardrobe').onclick=()=>Wardrobe.open(modal);
  }
  return {shop,workshop};
})();
